import {access} from './core.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rings=g=>g.type==='Polygon'?g.coordinates:g.coordinates.flat();
const path=g=>rings(g).map(r=>'M'+r.map(p=>p.map(n=>n.toFixed(3)).join(',')).join('L')+'Z').join('');
export function worldViewBox(world,zoom,pan){const [x,y,w,h]=world.bounds,p=Math.max(w,h)*.05;return [x-p+(w+2*p)*(1-1/zoom)/2+pan[0],y-p+(h+2*p)*(1-1/zoom)/2+pan[1],(w+2*p)/zoom,(h+2*p)/zoom];}
export function focusChapter(world,data,id){const ch=data.chapters.find(c=>c.id===id),ids=new Set([id,...ch.neighbors]),fs=world.features.filter(f=>ids.has(f.id));const x=Math.min(...fs.map(f=>f.mainlandBounds[0])),y=Math.min(...fs.map(f=>f.mainlandBounds[1])),right=Math.max(...fs.map(f=>f.mainlandBounds[2])),bottom=Math.max(...fs.map(f=>f.mainlandBounds[3]));const base=worldViewBox(world,1,[0,0]);return {zoom:Math.max(1,Math.min(8,Math.min(base[2]/((right-x)*1.25),base[3]/((bottom-y)*1.25)))),pan:[(x+right)/2-(base[0]+base[2]/2),(y+bottom)/2-(base[1]+base[3]/2)]};}
export function worldMarkup(world,data,state,currentId,zoom,pan){const a=access(data,state),vb=worldViewBox(world,zoom,pan),fs=Math.max(5,vb[2]*.022),ch=data.chapters.find(c=>c.id===currentId),near=new Set([currentId,...ch.neighbors]);const shapes=world.features.map(f=>`<path class="province ${a.chapters.has(f.id)?'available':'locked'} ${f.id===currentId?'active':''}" d="${path(f.geometry)}" fill-rule="evenodd" style="stroke-width:${vb[2]*.0018}" data-chapter="${f.id}" role="button" tabindex="0" aria-label="${esc(f.name)}"><title>${esc(f.name)}</title></path>`).join('');const names=world.features.filter(f=>zoom>=2||f.id===currentId).map(f=>`<text class="region-label" x="${f.center[0]}" y="${f.center[1]}" font-size="${fs}" text-anchor="middle" pointer-events="none">${esc(f.name)}</text>`).join('');const islands=world.labels.map(l=>`<text class="island-label" x="${l.point[0]}" y="${l.point[1]+12}" font-size="${fs}" text-anchor="middle" pointer-events="none">${esc(l.name)}</text>`).join('');return `<svg class="geographic-map national" viewBox="${vb.join(' ')}" role="group" aria-label="Bản đồ Việt Nam và các quần đảo">${shapes}${names}${islands}</svg>`;}
